<!doctype html>
<html lang="hu">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="color-scheme" content="light">
  <meta name="description" content="NOVA Studio - fiktív, északi ihletésű technológiai kiegészítők.">
  <title>NOVA Studio | Formába öntött egyszerűség</title>
  <style>
  :root{--ink:#1a2228;--muted:#6d7475;--cream:#f6f5f1;--stroke:#e9e8e2;--accent:#23494c;--light:#e3eee9;--white:#fff;--shadow:0 18px 52px rgba(17,39,40,.075)}
  *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--cream);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased}
  a{text-decoration:none;color:inherit}a:focus-visible{outline:3px solid #59b8aa;outline-offset:4px;border-radius:4px}
  .wrap{width:min(1160px,calc(100% - 64px));margin:auto}.micro{font-size:11px;font-weight:800;letter-spacing:.21em;text-transform:uppercase;color:#617276}
  .announcement{background:#224548;color:#e6f3ef;text-align:center;padding:11px 20px;font-size:12px;letter-spacing:.075em}.announcement b{font-weight:800;color:#d1e9e0}
  .nav{display:flex;align-items:center;justify-content:space-between;height:90px;gap:18px}.brand{display:inline-flex;align-items:center;gap:10px;font-size:25px;font-weight:900;letter-spacing:-.075em}.brand-mark{height:26px;width:26px;border:7px solid #255257;border-top-color:transparent;border-radius:8px;transform:rotate(45deg)}.brand-dot{color:#92a69f}
  .menu{display:flex;gap:32px;font-size:13px;font-weight:650;color:#4c595c}.menu a:hover{color:#0d7772}.nav-chip{border:1px solid #d0d8d4;border-radius:50px;padding:12px 18px;color:#294b4a;font-size:12px;font-weight:700;white-space:nowrap}
  .hero{display:grid;grid-template-columns:1fr .93fr;min-height:510px;background:#e3ece6;border:1px solid #d9e4dc;border-radius:22px;overflow:hidden;position:relative}
  .hero-text{padding:69px 0 62px 66px;position:relative;z-index:2}.eyebrow{display:flex;align-items:center;gap:11px;color:#346567;font-size:11px;font-weight:800;letter-spacing:.19em;text-transform:uppercase}.eyebrow:before{content:'';width:25px;height:1px;background:currentColor}
  h1{font-size:clamp(47px,5.4vw,76px);line-height:1.025;letter-spacing:-.073em;margin:30px 0 23px;font-weight:760;max-width:590px}h1 em{font-family:Georgia,serif;font-weight:400;color:#497b72;letter-spacing:-.065em}
  .lead{font-size:16px;line-height:1.75;color:#526a69;max-width:410px;margin:0 0 32px}.btn{display:inline-flex;align-items:center;gap:18px;background:#1c4144;color:#fff;padding:17px 23px;border-radius:9px;font-size:13px;font-weight:800;box-shadow:0 9px 17px rgba(25,67,64,.12)}.btn .arrow{font-size:19px;line-height:0}.btn:hover{background:#132f32}
  .hero-art{position:relative;min-width:0;display:flex;align-items:center;justify-content:center;background:radial-gradient(circle at 46% 47%,#f4f8ef 0,#dbe9e0 40%,#d6e5dc 74%)}.hero-art:before{content:'';position:absolute;width:360px;height:360px;left:50%;top:50%;transform:translate(-50%,-50%);border:1px solid rgba(61,105,99,.17);border-radius:50%;box-shadow:0 0 0 60px rgba(255,255,255,.11),0 0 0 120px rgba(255,255,255,.09)}
  .hero-art svg{position:relative;z-index:2;width:min(93%,440px);max-height:490px;filter:drop-shadow(0 20px 28px rgba(39,61,59,.14))}.hero-caption{position:absolute;right:28px;bottom:25px;z-index:3;color:#486b69;font-size:11px;letter-spacing:.12em;font-weight:800}
  .features{display:grid;grid-template-columns:repeat(3,1fr);gap:0;margin:36px 0 74px}.feature{display:flex;gap:15px;padding:2px 30px;border-right:1px solid #dddeda}.feature:first-child{padding-left:2px}.feature:last-child{border:0}.feature .icon{display:grid;place-items:center;flex:0 0 37px;height:37px;border:1px solid #d5dcd7;border-radius:12px;color:#416b68;font-size:18px}.feature strong{display:block;font-size:13px;letter-spacing:-.01em;margin:2px 0 5px}.feature span{font-size:12px;line-height:1.5;color:#7b8481}
  .section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:22px;margin:0 0 27px}.section-head h2{font-size:clamp(29px,3.6vw,42px);line-height:1.16;letter-spacing:-.06em;margin:10px 0 0}.section-note{font-size:13px;line-height:1.6;color:#77817d;max-width:255px;text-align:right;margin:0 0 5px}
  .products{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:17px}.product{background:var(--white);border:1px solid #e8e9e5;border-radius:15px;overflow:hidden;box-shadow:var(--shadow)}.product .pic{height:265px;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden;background:#f1eeef}.product .pic.tint-2{background:#f1f0e9}.product .pic.tint-3{background:#e9efeb}.product .pic.tint-4{background:#f4efea}.product .pic svg{width:99%;height:100%;display:block;transition:transform .3s ease}.product:hover .pic svg{transform:scale(1.035)}.product .tag{position:absolute;top:14px;left:14px;background:rgba(255,255,255,.86);backdrop-filter:blur(8px);border-radius:30px;padding:7px 11px;font-size:10px;font-weight:850;letter-spacing:.055em;color:#586562;z-index:2}
  .product .info{padding:20px 18px 23px}.product .category{font-size:10px;font-weight:750;letter-spacing:.13em;text-transform:uppercase;color:#8a9490}.product h3{font-size:19px;letter-spacing:-.04em;margin:7px 0 5px}.product .description{font-size:12px;color:#798580;line-height:1.55;min-height:40px;margin:0 0 16px}.product .bottom{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #ebefed;padding-top:15px}.product .price{font-size:15px;font-weight:850;letter-spacing:-.03em}.product .status{font-size:11px;font-weight:800;color:#57847b;background:#ebf4ee;padding:7px 10px;border-radius:30px}
  .editorial{display:grid;grid-template-columns:1fr 1fr;margin:87px 0 80px;border-radius:20px;overflow:hidden;background:#244a4a;color:white}.editorial-art{min-height:240px;background:linear-gradient(135deg,#a4c9ba,#d4e7d5);display:flex;align-items:center;justify-content:center;position:relative}.editorial-art .ring{border:1px solid rgba(255,255,255,.48);border-radius:100%;width:230px;height:230px;display:grid;place-items:center;box-shadow:0 0 0 45px rgba(255,255,255,.13),0 0 0 90px rgba(255,255,255,.08)}.editorial-art .shape{width:125px;height:125px;border:28px solid #204b4c;border-top-color:transparent;transform:rotate(-24deg);border-radius:38px}.editorial-text{padding:46px 55px}.editorial-text .micro{color:#aacdc4}.editorial-text h2{font-size:34px;line-height:1.12;letter-spacing:-.05em;margin:13px 0 16px}.editorial-text p{font-size:14px;line-height:1.75;color:#cadbd6;margin:0}
  footer{border-top:1px solid #dedfdc;padding:27px 0 42px;display:flex;justify-content:space-between;align-items:center;gap:12px}.footer-brand{font-size:20px;font-weight:900;letter-spacing:-.07em}.footer-note{font-size:11px;color:#87908b;text-align:right}
  @media(max-width:1000px){.hero-text{padding:54px 0 54px 45px}h1{font-size:59px}.product .pic{height:230px}.product .info{padding:16px 14px 20px}}
  @media(max-width:800px){.wrap{width:min(100% - 32px,660px)}.nav{height:75px}.menu{display:none}.nav-chip{padding:10px 13px}.hero{grid-template-columns:1fr}.hero-text{padding:49px 34px 36px}.hero-art{min-height:315px}.hero-art svg{width:min(77%,360px);max-height:310px}.hero-art:before{width:230px;height:230px}.features{grid-template-columns:1fr;gap:15px;margin:29px 0 54px}.feature,.feature:first-child{border-right:0;padding:0}.products{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.product .pic{height:230px}.editorial{grid-template-columns:1fr}.editorial-art{min-height:210px}.editorial-text{padding:36px}.section-head{align-items:flex-start}.section-note{display:none}}
  @media(max-width:480px){h1{font-size:46px}.hero-text{padding:40px 24px 31px}.lead{font-size:14px}.hero-art{min-height:245px}.hero-art svg{height:240px}.products{gap:10px}.product .pic{height:174px}.product .tag{top:10px;left:10px;font-size:9px;padding:6px 8px}.product .info{padding:13px 11px 14px}.product h3{font-size:17px}.product .description{font-size:11px;min-height:51px}.product .price{font-size:13px}.product .status{font-size:10px;padding:6px}.section-head h2{font-size:31px}.editorial{margin:64px 0}.editorial-text h2{font-size:30px}.announcement{font-size:10px;padding:10px 8px}.footer-note{font-size:10px}}

  </style>
</head>
